                                    1, 1, 1, 1, 1, 0, 1, 0,     // DDC1,      port 1037, Call 0
                                    0, 0, 0, 0, 0, 0, 0, 0      // DDC1,      port 1037, Call 1
                                    };
                                int[] FOUR_DDC_nstreams = new int[3]
                                    {
                                    1,                          // DDC0,      port 1035
