                                    1, 1, 1, 1, 1, 1, 1, 1,     // Rx3, port 1038, Call 1
                                    2, 2, 2, 2, 2, 2, 2, 2,     // Rx4, port 1039, Call 0
                                    2, 2, 2, 2, 2, 2, 2, 2,     // Rx4, port 1039, Call 1
